"use strict";(self.webpackChunkinnercore_docs=self.webpackChunkinnercore_docs||[]).push([["266"],{86164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/docs/getting-started/methodology","label":"Methodology","docId":"getting-started/methodology","unlisted":false},{"type":"link","href":"/docs/getting-started/installing-pack","label":"Installing the Engine","docId":"getting-started/installing-pack","unlisted":false},{"type":"link","href":"/docs/getting-started/supporting-ides","label":"Supported IDEs","docId":"getting-started/supporting-ides","unlisted":false},{"type":"link","href":"/docs/getting-started/going-forward","label":"Going Forward","docId":"getting-started/going-forward","unlisted":false}],"collapsible":true,"href":"/docs/category/getting-started"},{"type":"category","label":"Basics","items":[{"type":"link","href":"/docs/basics/mod-structure","label":"Mod Structure","docId":"basics/mod-structure","unlisted":false},{"type":"link","href":"/docs/basics/mod-lifecycle","label":"Mod Lifecycle","docId":"basics/mod-lifecycle","unlisted":false},{"type":"link","href":"/docs/basics/building-script","label":"Building Scripts","docId":"basics/building-script","unlisted":false},{"type":"link","href":"/docs/basics/evaluate-context","label":"Evaluate Context","docId":"basics/evaluate-context","unlisted":false},{"type":"link","href":"/docs/basics/integrating-libraries","label":"Integrating Libraries","docId":"basics/integrating-libraries","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/basics"},{"type":"category","label":"Events","items":[{"type":"link","href":"/docs/events/where-what-and-who","label":"Where, what and who","docId":"events/where-what-and-who","unlisted":false},{"type":"link","href":"/docs/events/callbacks","label":"Callbacks","docId":"events/callbacks","unlisted":false},{"type":"link","href":"/docs/events/updatables","label":"Updatables","docId":"events/updatables","unlisted":false},{"type":"link","href":"/docs/events/threading","label":"Threading","docId":"events/threading","unlisted":false},{"type":"link","href":"/docs/events/using-synced-data","label":"using-synced-data","docId":"events/using-synced-data","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/events"},{"type":"category","label":"Items","items":[{"type":"link","href":"/docs/items/first-item","label":"First Item","docId":"items/first-item","unlisted":false},{"type":"link","href":"/docs/items/food-armor-and-throwables","label":"Food, Armor and Snowballs","docId":"items/food-armor-and-throwables","unlisted":false},{"type":"link","href":"/docs/items/recipes","label":"Recipes","docId":"items/recipes","unlisted":false},{"type":"category","label":"Extra","items":[{"type":"link","href":"/docs/items/extra/what-is-extra","label":"What is extra?","docId":"items/extra/what-is-extra","unlisted":false},{"type":"link","href":"/docs/items/extra/enchanting","label":"enchanting","docId":"items/extra/enchanting","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/extra"},{"type":"link","href":"/docs/items/tools","label":"tools","docId":"items/tools","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/items"},{"type":"category","label":"Blocks","items":[{"type":"link","href":"/docs/blocks/first-block","label":"First Block","docId":"blocks/first-block","unlisted":false},{"type":"link","href":"/docs/blocks/first-liquid","label":"First Liquid","docId":"blocks/first-liquid","unlisted":false},{"type":"category","label":"Models","items":[{"type":"link","href":"/docs/blocks/renders/vanilla-shapes","label":"In-game Shapes","docId":"blocks/renders/vanilla-shapes","unlisted":false},{"type":"link","href":"/docs/blocks/renders/block-renderer","label":"Block Models","docId":"blocks/renders/block-renderer","unlisted":false},{"type":"link","href":"/docs/blocks/renders/conditioning","label":"conditioning","docId":"blocks/renders/conditioning","unlisted":false},{"type":"link","href":"/docs/blocks/renders/customizing-item","label":"customizing-item","docId":"blocks/renders/customizing-item","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/models"},{"type":"link","href":"/docs/blocks/block-entities","label":"block-entities","docId":"blocks/block-entities","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/blocks"},{"type":"category","label":"Environment","items":[{"type":"link","href":"/docs/environment/modifying-region","label":"Modifying the Region","docId":"environment/modifying-region","unlisted":false},{"type":"link","href":"/docs/environment/game-objects","label":"game-objects","docId":"environment/game-objects","unlisted":false},{"type":"link","href":"/docs/environment/animation","label":"animation","docId":"environment/animation","unlisted":false},{"type":"link","href":"/docs/environment/particles","label":"Particles and Emitters","docId":"environment/particles","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/environment"},{"type":"category","label":"Entities","items":[{"type":"link","href":"/docs/entities/actoring-entities","label":"Processing Entities","docId":"entities/actoring-entities","unlisted":false},{"type":"link","href":"/docs/entities/first-entity","label":"First Entity","docId":"entities/first-entity","unlisted":false},{"type":"category","label":"Renders","items":[{"type":"link","href":"/docs/entities/renders/rendering-basics","label":"rendering-basics","docId":"entities/renders/rendering-basics","unlisted":false},{"type":"link","href":"/docs/entities/renders/animating-in-runtime","label":"animating-in-runtime","docId":"entities/renders/animating-in-runtime","unlisted":false},{"type":"link","href":"/docs/entities/renders/attaching-renders","label":"attaching-renders","docId":"entities/renders/attaching-renders","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/renders"},{"type":"link","href":"/docs/entities/path-navigation","label":"path-navigation","docId":"entities/path-navigation","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/entities"},{"type":"category","label":"UIs","items":[{"type":"link","href":"/docs/ui/investigating-contents","label":"Investigating contents","docId":"ui/investigating-contents","unlisted":false},{"type":"link","href":"/docs/ui/drawings","label":"Background layout","docId":"ui/drawings","unlisted":false},{"type":"link","href":"/docs/ui/elements","label":"Elements","docId":"ui/elements","unlisted":false},{"type":"link","href":"/docs/ui/window-types","label":"window-types","docId":"ui/window-types","unlisted":false},{"type":"category","label":"Advanced","key":"Advanced UI","items":[{"type":"link","href":"/docs/ui/advanced/animating-elements","label":"Animating elements","docId":"ui/advanced/animating-elements","unlisted":false},{"type":"link","href":"/docs/ui/advanced/extending-components","label":"Extending components","docId":"ui/advanced/extending-components","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/advanced"}],"collapsed":true,"collapsible":true,"href":"/docs/category/uis"},{"type":"category","label":"Storage","items":[{"type":"link","href":"/docs/storage/saving-basics","label":"Saving Data","docId":"storage/saving-basics","unlisted":false},{"type":"link","href":"/docs/storage/principles-and-objectives","label":"principles-and-objectives","docId":"storage/principles-and-objectives","unlisted":false},{"type":"link","href":"/docs/storage/containers","label":"containers","docId":"storage/containers","unlisted":false},{"type":"link","href":"/docs/storage/tile-entities","label":"tile-entities","docId":"storage/tile-entities","unlisted":false},{"type":"link","href":"/docs/storage/processing-resources","label":"processing-resources","docId":"storage/processing-resources","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/storage"},{"type":"category","label":"Multiplayer","items":[{"type":"link","href":"/docs/multiplayer/start","label":"Getting Started","docId":"multiplayer/start","unlisted":false},{"type":"link","href":"/docs/multiplayer/client-packets","label":"Client Packets","docId":"multiplayer/client-packets","unlisted":false},{"type":"link","href":"/docs/multiplayer/server-packets","label":"Server Packets","docId":"multiplayer/server-packets","unlisted":false},{"type":"link","href":"/docs/multiplayer/network-entity-type","label":"network-entity-type","docId":"multiplayer/network-entity-type","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/multiplayer"},{"type":"category","label":"Dimensions","items":[{"type":"link","href":"/docs/dimensions/ore-with-manual-generation","label":"Ore with Manual Generation","docId":"dimensions/ore-with-manual-generation","unlisted":false},{"type":"link","href":"/docs/dimensions/first-dimension","label":"first-dimension","docId":"dimensions/first-dimension","unlisted":false},{"type":"link","href":"/docs/dimensions/creating-biomes","label":"creating-biomes","docId":"dimensions/creating-biomes","unlisted":false},{"type":"link","href":"/docs/dimensions/investigating-generators","label":"investigating-generators","docId":"dimensions/investigating-generators","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/dimensions"},{"type":"category","label":"Advanced","items":[{"type":"link","href":"/docs/advanced/named-binary-tag","label":"named-binary-tag","docId":"advanced/named-binary-tag","unlisted":false},{"type":"link","href":"/docs/advanced/wrapping-packages","label":"wrapping-packages","docId":"advanced/wrapping-packages","unlisted":false},{"type":"link","href":"/docs/advanced/shaders-and-materials","label":"shaders-and-materials","docId":"advanced/shaders-and-materials","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/advanced-1"},{"type":"category","label":"Publishing","items":[{"type":"link","href":"/docs/publishing/connecting-integrations","label":"connecting-integrations","docId":"publishing/connecting-integrations","unlisted":false},{"type":"link","href":"/docs/publishing/debugging","label":"debugging","docId":"publishing/debugging","unlisted":false},{"type":"link","href":"/docs/publishing/packing-to-publish","label":"packing-to-publish","docId":"publishing/packing-to-publish","unlisted":false},{"type":"link","href":"/docs/publishing/uploading-and-community","label":"uploading-and-community","docId":"publishing/uploading-and-community","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/category/publishing"},{"type":"link","href":"/docs/future-steps","label":"future-steps","docId":"future-steps","unlisted":false}]},"docs":{"advanced/debugging-abilities":{"id":"advanced/debugging-abilities","title":"TODO","description":"Do not misuse!"},"advanced/named-binary-tag":{"id":"advanced/named-binary-tag","title":"named-binary-tag","description":"","sidebar":"tutorialSidebar"},"advanced/shaders-and-materials":{"id":"advanced/shaders-and-materials","title":"shaders-and-materials","description":"","sidebar":"tutorialSidebar"},"advanced/wrapping-packages":{"id":"advanced/wrapping-packages","title":"wrapping-packages","description":"","sidebar":"tutorialSidebar"},"basics/building-script":{"id":"basics/building-script","title":"Building Scripts","description":"Besides the ability to directly set an executable script, there is often a need to divide the source code into files. As soon as the project starts to contain the first classes, utility functions, and other things that should be separated, working in a single file becomes simply impossible. This is where build files and advanced toolchain settings come to our aid.","sidebar":"tutorialSidebar"},"basics/evaluate-context":{"id":"basics/evaluate-context","title":"Evaluate Context","description":"Defines the space in which all your code is located. It stores the values of variables and constants, functions and transformed classes, and also performs future code interactions with the space.","sidebar":"tutorialSidebar"},"basics/integrating-libraries":{"id":"basics/integrating-libraries","title":"Integrating Libraries","description":"Implemented from any mod script. Libraries expand the capabilities of the game, or simplify the creation of existing ones. In addition, you can even allocate part of your code to use it as a library; these are regular scripts, the context of which will now be considered.","sidebar":"tutorialSidebar"},"basics/mod-lifecycle":{"id":"basics/mod-lifecycle","title":"Mod Lifecycle","description":"Usually begins before launching the game, at this moment the mod announces its existence to the launcher and performs a list of necessary procedures for the user. Now we will look at the complete cycle from this moment to closing the game, what happens in the mod during various events and how it can affect the gameplay.","sidebar":"tutorialSidebar"},"basics/mod-structure":{"id":"basics/mod-structure","title":"Mod Structure","description":"Before using one of the template creation options, it will probably be an equally important part to familiarize yourself with their contents. First of all, a mod is a folder with a configuration file build.config, which describes the entire process of loading, compiling and building your mod. Let\'s look at the contents of the entire folder, and first analyze other, but no less important aspects.","sidebar":"tutorialSidebar"},"blocks/block-entities":{"id":"blocks/block-entities","title":"block-entities","description":"","sidebar":"tutorialSidebar"},"blocks/first-block":{"id":"blocks/first-block","title":"First Block","description":"The whole world of Minecraft consists of blocks. The player and entities move on them, mining them allows the player to extract resources and create new blocks to craft even more blocks, and some can be opened or interacted with in some way. Let\'s start by looking at textures, and then, we\'ll create blocks with different variations.","sidebar":"tutorialSidebar"},"blocks/first-liquid":{"id":"blocks/first-liquid","title":"First Liquid","description":"Liquids are blocks that spread over a plane, which usually make it difficult for entities to move on them and form currents. In-game liquids include water and lava.","sidebar":"tutorialSidebar"},"blocks/renders/block-renderer":{"id":"blocks/renders/block-renderer","title":"Block Models","description":"If we try to describe the purpose of ICRender in two words, it turns out that block shapes or models perfectly fit it. This technology will allow you to link newly created models to a specific block, place the desired model at coordinates, dynamically update renders, physical and visual shapes of blocks, and perhaps even replace models of regular items altogether. Let\'s start by reviewing BlockRenderer models and end with a few shapes for a variety of purposes.","sidebar":"tutorialSidebar"},"blocks/renders/conditioning":{"id":"blocks/renders/conditioning","title":"conditioning","description":"","sidebar":"tutorialSidebar"},"blocks/renders/customizing-item":{"id":"blocks/renders/customizing-item","title":"customizing-item","description":"","sidebar":"tutorialSidebar"},"blocks/renders/vanilla-shapes":{"id":"blocks/renders/vanilla-shapes","title":"In-game Shapes","description":"In addition to the standard \\"full-block\\" blocks, shapes can be very diverse. The game provides various variations of basic models, such as stairs or slabs. Usually, their implementations are used in conjunction with standard, full-block blocks. Here is presented the majority of existing shapes, as well as various types of atlas texture blending.","sidebar":"tutorialSidebar"},"dimensions/creating-biomes":{"id":"dimensions/creating-biomes","title":"creating-biomes","description":"","sidebar":"tutorialSidebar"},"dimensions/first-dimension":{"id":"dimensions/first-dimension","title":"first-dimension","description":"","sidebar":"tutorialSidebar"},"dimensions/investigating-generators":{"id":"dimensions/investigating-generators","title":"investigating-generators","description":"","sidebar":"tutorialSidebar"},"dimensions/ore-with-manual-generation":{"id":"dimensions/ore-with-manual-generation","title":"Ore with Manual Generation","description":"Usually, ore generation comes down to a couple of methods, but it is limited by the shape and method of generation. We will use the built-in generator, consider options for creating our own generators and generate several shapes.","sidebar":"tutorialSidebar"},"entities/actoring-entities":{"id":"entities/actoring-entities","title":"Processing Entities","description":"An entity is a soft physical body that \\"lives\\" and moves around the world. In addition to the physical part, entities (or mobs) have a visual part, it does not determine the physical shape, but only allows you to display the entity in the game. Often you can interact with an entity, for example, to obtain resources or exchange some for others. Let\'s get acquainted with the possibilities of processing them.","sidebar":"tutorialSidebar"},"entities/first-entity":{"id":"entities/first-entity","title":"First Entity","description":"The concept of creating entities is somewhat different from everything else, a script will not work for this, it is much more convenient to use behavior and resource packs. This article describes many new concepts not described previously, however we will get acquainted with most of them. Let\'s start with the foundation of a new mob, and later move on to describing its behavior and creating the visual part.","sidebar":"tutorialSidebar"},"entities/path-navigation":{"id":"entities/path-navigation","title":"path-navigation","description":"","sidebar":"tutorialSidebar"},"entities/renders/animating-in-runtime":{"id":"entities/renders/animating-in-runtime","title":"animating-in-runtime","description":"","sidebar":"tutorialSidebar"},"entities/renders/attaching-renders":{"id":"entities/renders/attaching-renders","title":"attaching-renders","description":"","sidebar":"tutorialSidebar"},"entities/renders/rendering-basics":{"id":"entities/renders/rendering-basics","title":"rendering-basics","description":"","sidebar":"tutorialSidebar"},"environment/animation":{"id":"environment/animation","title":"animation","description":"","sidebar":"tutorialSidebar"},"environment/game-objects":{"id":"environment/game-objects","title":"game-objects","description":"","sidebar":"tutorialSidebar"},"environment/modifying-region":{"id":"environment/modifying-region","title":"Modifying the Region","description":"The game world consists of chunks \u2014 components of a region, they contain blocks and entities that form the environment. The number of regions is unlimited, they are tied to the dimension. Specifically for linking regions to each other, a block source was created, for the developer it is only important to determine which dimension they will interact with, and a special handler will take care of the processing. Let\'s consider the capabilities of the environment, modifying and getting properties, spawning entities and placing blocks.","sidebar":"tutorialSidebar"},"environment/particles":{"id":"environment/particles","title":"Particles and Emitters","description":"Particles are two-dimensional, usually uniformly accelerated, bodies in game space. They are emitted during interactions with blocks, from blocks themselves during their operation, destruction of tools and much, much, much more. Emitters determine \\"sources\\"; those places relative to which particles will, for example, move. Emitters allow you to redefine linear accelerations of emitted particles, significantly expanding the scope of their application.","sidebar":"tutorialSidebar"},"events/callbacks":{"id":"events/callbacks","title":"Callbacks","description":"From the phrase call + back, it is with their help that we will register event handlers. As the name implies, we will receive a call, and then we can cancel further action. However, not all actions can be canceled, and those that can be can be canceled either by another mod or by the engine. But let\'s focus on handling callbacks.","sidebar":"tutorialSidebar"},"events/threading":{"id":"events/threading","title":"Threading","description":"Multithreading is of paramount importance for any modern system, environment, application, and simply for a script. But not in the case of Minecraft. This game uses one thread for practically everything: rendering interfaces, world generation, rendering entities, and more. So far this works identically on all editions of the game, creating performance issues and raising system requirements. But is everything really so bad and when can you use multiple threads, and also, why do we even need this. Let\'s figure it out.","sidebar":"tutorialSidebar"},"events/updatables":{"id":"events/updatables","title":"Updatables","description":"These are objects built around an update function. Updates are called every tick (1/20 of a second), which can interact with the world in any way and perform long-term operations. An integral part of the engine, on which most of the life cycle is based.","sidebar":"tutorialSidebar"},"events/using-synced-data":{"id":"events/using-synced-data","title":"using-synced-data","description":"","sidebar":"tutorialSidebar"},"events/where-what-and-who":{"id":"events/where-what-and-who","title":"Where, what and who","description":"This principle is how most of the events we are going to learn about work. Let\'s start with what is generally understood as an event? In addition to the obvious in-game events, events can depend on other mods, be called randomly or with a certain periodicity, and even come from the server side. We will consider each of these types, but not immediately, and not even in this chapter, but only when they are really needed.","sidebar":"tutorialSidebar"},"future-steps":{"id":"future-steps","title":"future-steps","description":"","sidebar":"tutorialSidebar"},"getting-started/developers-everywhere":{"id":"getting-started/developers-everywhere","title":"Developers Everywhere","description":"Participants in this dialogue:"},"getting-started/going-forward":{"id":"getting-started/going-forward","title":"Going Forward","description":"Once the necessary tools or environments have been installed, you can proceed directly to learning languages and creating a project. Regardless of the chosen programming language and project idea, it is important to maintain interest and motivation, as programming can be a complex and lengthy process.","sidebar":"tutorialSidebar"},"getting-started/installing-pack":{"id":"getting-started/installing-pack","title":"Installing the Engine","description":"Before creating or simply installing modifications, we need to prepare tools for modifying the game. Why can\'t I modify the game directly? By default, Minecraft is closed-source and does not allow for gameplay modification, except perhaps for behavior packs.","sidebar":"tutorialSidebar"},"getting-started/methodology":{"id":"getting-started/methodology","title":"Methodology","description":"Any project one way or another has some summary of basic terms, in which any of us should easily navigate, not forgetting basic concepts. It is important to remember that Minecraft is a game that encourages creativity and freedom of action, so there are no strict rules or limitations in methodology. However, one can describe the general steps and approaches that can be used when playing or creating mods for it.","sidebar":"tutorialSidebar"},"getting-started/supporting-ides":{"id":"getting-started/supporting-ides","title":"Supported IDEs","description":"An environment simplifies project development by providing auto-completion, error checking, compilation of low-level languages, and a whole bunch of features. Writing code in an environment is much more convenient than using a notepad, although, however, the choice is entirely yours.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"On the home page of the documentation for the Inner Core engine, which extends the base functionality of Minecraft on Android devices. The task of this site is to teach the capabilities of creating changes to the gameplay \u2014 modifications, bringing your own idea to the game, and just learning something new.","sidebar":"tutorialSidebar"},"items/extra/enchanting":{"id":"items/extra/enchanting","title":"enchanting","description":"","sidebar":"tutorialSidebar"},"items/extra/what-is-extra":{"id":"items/extra/what-is-extra","title":"What is extra?","description":"As we know, there are many items in the game. And each of them can have its own data. Such items are items that have the same identifier, but at the same time cannot be stacked into one stack and differ in some way. One of such items is an enchanted book.","sidebar":"tutorialSidebar"},"items/first-item":{"id":"items/first-item","title":"First Item","description":"We call items things that are in the inventory or a container. This broad category includes crafting materials, food, tools, armor, and the like. There are even useless items, like poisonous potatoes. The player can interact with them, equip them, throw them, or eat them; these are the main game objects for the world and the beginning of learning.","sidebar":"tutorialSidebar"},"items/food-armor-and-throwables":{"id":"items/food-armor-and-throwables","title":"Food, Armor and Snowballs","description":"Let\'s superficially look at the basics of each type of items. The syntax of their implementation in most cases coincides with the standard item creation, however additional arguments appear for each of them. Examine their description again if necessary. The only difference in registering third-party item types from regular ones is the last argument with parameters. And of course, other types have properties and events unique to them.","sidebar":"tutorialSidebar"},"items/recipes":{"id":"items/recipes","title":"Recipes","description":"Items in the game, in addition to being simply found in various structures, are crafted on a crafting table, smelted in a furnace, or obtained as a result of mechanisms and rituals. Everything except the last must be registered as a recipe, which will be considered now.","sidebar":"tutorialSidebar"},"items/tools":{"id":"items/tools","title":"tools","description":"","sidebar":"tutorialSidebar"},"multiplayer/client-packets":{"id":"multiplayer/client-packets","title":"Client Packets","description":"Client packets are one of the things that almost no magic mod can do without.","sidebar":"tutorialSidebar"},"multiplayer/network-entity-type":{"id":"multiplayer/network-entity-type","title":"network-entity-type","description":"","sidebar":"tutorialSidebar"},"multiplayer/server-packets":{"id":"multiplayer/server-packets","title":"Server Packets","description":"Oh, you\'re back here. Thank you for reading us!","sidebar":"tutorialSidebar"},"multiplayer/start":{"id":"multiplayer/start","title":"Getting Started","description":"Multiplayer is one of the most important parts of any non-client mod that the creator needs to support so that players can play the mod together. And at the same time, one of the most difficult for beginners.","sidebar":"tutorialSidebar"},"publishing/connecting-integrations":{"id":"publishing/connecting-integrations","title":"connecting-integrations","description":"","sidebar":"tutorialSidebar"},"publishing/debugging":{"id":"publishing/debugging","title":"debugging","description":"","sidebar":"tutorialSidebar"},"publishing/packing-to-publish":{"id":"publishing/packing-to-publish","title":"packing-to-publish","description":"","sidebar":"tutorialSidebar"},"publishing/uploading-and-community":{"id":"publishing/uploading-and-community","title":"uploading-and-community","description":"","sidebar":"tutorialSidebar"},"readme":{"id":"readme","title":"Start your Journey","description":"\x3c!--","sidebar":"tutorialSidebar"},"storage/containers":{"id":"storage/containers","title":"containers","description":"","sidebar":"tutorialSidebar"},"storage/principles-and-objectives":{"id":"storage/principles-and-objectives","title":"principles-and-objectives","description":"","sidebar":"tutorialSidebar"},"storage/processing-resources":{"id":"storage/processing-resources","title":"processing-resources","description":"","sidebar":"tutorialSidebar"},"storage/saving-basics":{"id":"storage/saving-basics","title":"Saving Data","description":"Usually certain data is attributed to the world, while others must be unique for each player. This determines which saves and by whom they should be processed. The methods of saving are different, the types of data too, so let\'s look at the main ones.","sidebar":"tutorialSidebar"},"storage/tile-entities":{"id":"storage/tile-entities","title":"tile-entities","description":"","sidebar":"tutorialSidebar"},"structures/index":{"id":"structures/index","title":"index","description":""},"structures/patching-instructions":{"id":"structures/patching-instructions","title":"TODO","description":"The described methods concern structure generation on the server."},"ui/advanced/animating-elements":{"id":"ui/advanced/animating-elements","title":"Animating elements","description":"Animation allows you to make game interfaces more lively and dynamic: be it the smooth appearance and disappearance of windows, the movement of individual elements, or changing their properties over time. In this article, we will look at basic approaches to creating animations, working with elements outside the main thread, and some pitfalls.","sidebar":"tutorialSidebar"},"ui/advanced/extending-components":{"id":"ui/advanced/extending-components","title":"Extending components","description":"In addition to standard elements and background components, new ones can be created based on a special component. Let\'s look at the components and events that can be handled using them.","sidebar":"tutorialSidebar"},"ui/drawings":{"id":"ui/drawings","title":"Background layout","description":"Forms the window space, visually indicating its boundaries and adding background objects as needed. These components are always under the main elements, and like any other components, are drawn on the canvas as the content of your window.","sidebar":"tutorialSidebar"},"ui/elements":{"id":"ui/elements","title":"Elements","description":"Perform most of the functions required of the interface. The element processes user actions and changes based on them, switching its state or reporting an interaction to the window. Like any other component, the element is drawn on the canvas, but can also dynamically change its content.","sidebar":"tutorialSidebar"},"ui/investigating-contents":{"id":"ui/investigating-contents","title":"Investigating contents","description":"The interface in Inner Core is built on the basis of the Android graphical shell, all elements of which are drawn on a single canvas for each window. Displaying occurs on top of the gameplay, which does not allow modifying the in-game interface, but extends the capabilities of working with content.","sidebar":"tutorialSidebar"},"ui/window-types":{"id":"ui/window-types","title":"window-types","description":"","sidebar":"tutorialSidebar"}}}}')}}]);